<script setup>
import { ArrowLeft, ArrowUpRight, Search, SlidersHorizontal, TrendingUp, WalletCards } from 'lucide-vue-next'
import { computed, ref } from 'vue'
import MarketTable from './MarketTable.vue'
import PayoffExplorer from './PayoffExplorer.vue'
import { brand } from '../brand.js'

const props = defineProps({ path: { type: String, default: '/app/markets' } })
const emit = defineEmits(['navigate'])
const query = ref('')
const side = ref('All')
const showFilters = ref(false)
const symbols = ['SOL', 'JUP', 'BONK', 'USDC']
const symbol = computed(() => {
  const match = props.path.match(/\/app\/markets\/([^/]+)/i)
  return match && symbols.includes(match[1].toUpperCase()) ? match[1].toUpperCase() : ''
})
const pageTitle = computed(() => props.path.includes('launchpad') ? 'Launchpad' : props.path.includes('auctions') ? 'Auctions' : props.path.includes('recompose') ? 'Recompose' : symbol.value ? `${symbol.value} market` : 'Markets')
const copy = computed(() => ({ Markets: 'Scan defined-cap series and compare the two sides of each market.', Launchpad: 'Record a candidate market for a future verified listing.', Auctions: 'Review the sample Upside auction surface without placing an order.', Recompose: 'Pair Income and Upside positions back into one market unit.' }[pageTitle.value] || 'Read the illustrative settlement path for this asset.'))
</script>

<template>
  <section class="workspace container">
    <div class="workspace-head"><div><p class="workspace-kicker"><span class="status-dot"></span>{{ brand.network }} / paper market</p><h1 tabindex="-1">{{ pageTitle }}</h1><p class="workspace-lede">{{ copy }}</p></div><a href="/" class="workspace-back" @click.prevent="emit('navigate','/')"><ArrowLeft :size="15" /> Markets</a></div>
    <div v-if="symbol" class="asset-detail"><div class="detail-summary"><span class="detail-coin">{{ symbol.slice(0, 1) }}</span><div><span class="detail-label">Example series</span><h2>{{ symbol }} / {{ brand.network }}</h2><p>30-day epoch | +5% cap | illustrative values</p></div><span class="paper-badge">PAPER ONLY</span></div><div class="detail-metrics"><div><span>Reference</span><strong>{{ symbol === 'SOL' ? '$182.00' : symbol === 'JUP' ? '$1.12' : symbol === 'BONK' ? '$0.000021' : '$1.00' }}</strong></div><div><span>Income model</span><strong class="mint">+5% cap</strong></div><div><span>Settlement</span><strong>Not live</strong></div></div><PayoffExplorer :spot="symbol === 'SOL' ? 182 : symbol === 'JUP' ? 1.12 : symbol === 'BONK' ? 0.000021 : 1" :asset="symbol" /></div>
    <div v-else-if="pageTitle === 'Launchpad'" class="workspace-card launchpad-card"><div class="card-icon"><WalletCards :size="19" /></div><p class="workspace-kicker">Listing intake</p><h2>Suggest a market.</h2><p>Any SPL market unit with a verified price feed and USDC liquidity path may qualify. This preview records no wallet request or listing transaction.</p><a href="/docs#listing" class="action-link" @click.prevent="emit('navigate','/docs#listing')">Read listing notes <ArrowUpRight :size="15" /></a></div>
    <div v-else-if="pageTitle === 'Recompose'" class="workspace-card"><div class="card-icon"><TrendingUp :size="19" /></div><p class="workspace-kicker">Income + Upside</p><h2>One asset again.</h2><p>Recomposition would require a wallet transaction. The local preview keeps this action visible while execution remains unavailable.</p><button class="action-button" type="button" disabled>Recompose unavailable</button></div>
    <template v-else><div class="stats-strip"><div><span>Value locked</span><strong>—</strong></div><div><span>Premium / net</span><strong>—</strong></div><div><span>Epochs settled</span><strong>0</strong></div><div><span>Active series</span><strong>4</strong></div></div><div class="filters"><label class="search-field"><Search :size="16" /><span class="sr-only">Search markets</span><input v-model="query" placeholder="Search token or market" /></label><div class="side-tabs" aria-label="Position type"><button v-for="option in ['All','Income','Upside']" :key="option" :aria-pressed="side === option" :class="{active:side===option}" @click="side=option">{{ option }}</button></div><button class="filter-button" type="button" :aria-expanded="showFilters" @click="showFilters = !showFilters"><SlidersHorizontal :size="15" /> Details</button></div><p v-if="showFilters" class="filter-details">All examples use a +5% cap, 30-day epoch and 25% model volatility.</p><MarketTable :query="query" :side="side" @reset="query = ''" @navigate="to => emit('navigate',to)" /></template>
  </section>
</template>

<style scoped>
.workspace{padding:32px 0 76px}.workspace-head{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;padding:0 0 22px;border-bottom:1px solid var(--line)}.workspace-kicker,.detail-label,.stats-strip span,.paper-badge{color:var(--muted);font:600 10px/1.4 var(--mono,monospace);letter-spacing:.09em;text-transform:uppercase}.workspace-kicker{color:var(--accent)}.status-dot{display:inline-block;width:7px;height:7px;margin-right:7px;border-radius:50%;background:var(--mint);box-shadow:0 0 10px var(--mint)}h1{margin:9px 0 7px;font-size:32px;line-height:1.1;margin:0;color:var(--muted);font-size:14px;line-height:1.55}.workspace-back,.action-link{display:inline-flex;align-items:center;gap:7px;color:var(--mint);font:600 11px var(--mono,monospace);text-decoration:none}.stats-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;margin:18px 0;border:1px solid var(--line);background:var(--line)}.stats-strip div{display:grid;gap:8px;padding:14px;background:var(--surface)}.stats-strip strong{font:500 20px var(--mono,monospace);color:var(--fg)}.filters{display:flex;align-items:center;gap:8px;margin:16px 0 12px}.search-field{display:flex;align-items:center;gap:8px;max-width:320px;flex:1;height:38px;padding:0 11px;color:var(--muted);border:1px solid var(--line);background:var(--panel)}.search-field input{width:100%;border:0;outline:0;background:none;color:var(--fg);font:12px var(--mono,monospace)}.side-tabs{display:flex;gap:3px}.side-tabs button,.filter-button{height:38px;padding:0 12px;border:1px solid var(--line);background:var(--surface);color:var(--muted);font:11px var(--mono,monospace);cursor:pointer}.side-tabs button.active,.side-tabs button:hover{border-color:var(--mint);background:#1b2b20;color:var(--mint)}.filter-button{display:inline-flex;align-items:center;gap:6px;margin-left:auto}.filter-details{margin:0 0 12px;padding:10px 12px;border-left:2px solid var(--accent);background:#282e1c;color:var(--accent);font:11px var(--mono,monospace)}.workspace-card{max-width:800px;margin-top:28px;padding:26px;border:1px solid var(--line);background:var(--surface)}.card-icon,.detail-coin{display:grid;place-items:center;width:38px;height:38px;color:var(--mint);border:1px solid #75d8a855;background:#1b2b20}.workspace-card h2{margin:14px 0 9px;font-size:28px}.workspace-card p:not(.workspace-kicker){max-width:590px;color:var(--muted);font-size:13px;line-height:1.65}.action-button{min-height:38px;padding:0 13px;color:var(--muted);border:1px solid var(--line);background:var(--panel);font:11px var(--mono,monospace)}.asset-detail{margin-top:18px}.detail-summary{display:flex;align-items:center;gap:13px;padding:16px;border:1px solid var(--line);background:var(--surface)}.detail-coin{flex:none;width:44px;height:44px;font:700 18px var(--mono,monospace)}.detail-summary h2{margin:3px 0;font-size:22px}.detail-summary p{margin:0;color:var(--muted);font-size:12px}.paper-badge{margin-left:auto;padding:6px 8px;color:var(--accent);border:1px solid #667735;background:#2b2618}.detail-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin:10px 0 18px;background:var(--line)}.detail-metrics div{display:grid;gap:7px;padding:13px;background:var(--panel)}.detail-metrics span{color:var(--muted);font:10px var(--mono,monospace);text-transform:uppercase}.detail-metrics strong{font:500 16px var(--mono,monospace)}.mint{color:var(--mint)}@media(max-width:700px){.workspace{padding:24px 0 62px}.workspace-head{display:block}.workspace-back{margin-top:17px}.stats-strip{grid-template-columns:1fr 1fr}.filters{flex-wrap:wrap}.search-field{max-width:none;flex-basis:100%}.filter-button{margin-left:0}.detail-summary{align-items:flex-start}.paper-badge{font-size:8px}.detail-metrics strong{font-size:13px}}
</style>

